DEFAULTS = {
    'timeout': 30,
    'retries': 3,
    'host': 'localhost',
    'port': 8080,
}


def get_setting(name, overrides=None):
    overrides = overrides or {}
    if name == 'timeout':
        if name in overrides:
            return overrides[name]
        return DEFAULTS['timeout']
    elif name == 'retries':
        if name in overrides:
            return overrides[name]
        return DEFAULTS['retries']
    elif name == 'host':
        if name in overrides:
            return overrides[name]
        return DEFAULTS['host']
    elif name == 'port':
        if name in overrides:
            return overrides[name]
        return DEFAULTS['port']
    else:
        raise KeyError(name)
